package com.example.billing.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="UsageRecords",uniqueConstraints=@UniqueConstraint(name="IX_UsageRecords_IdempotencyKey",columnNames="IdempotencyKey"),indexes={@Index(name="IX_UsageRecords_SubscriptionId",columnList="SubscriptionId"),@Index(name="IX_UsageRecords_Timestamp",columnList="Timestamp")}) public class UsageRecord { @Id @Column(name="Id") public UUID id; @Column(name="CustomerId",nullable=false) public UUID customerId; @Column(name="SubscriptionId",nullable=false) public UUID subscriptionId; @Column(name="MetricName",length=100,nullable=false) public String metricName; @Column(name="Quantity",precision=18,scale=4,nullable=false) public BigDecimal quantity; @Column(name="Timestamp",nullable=false) public OffsetDateTime timestamp; @Column(name="IdempotencyKey",length=200,nullable=false) public String idempotencyKey; }
